import {COLORS,STEPS,ATTRS,PROFILES,uid,clone,clamp,block,layout,makeCharacter,blank,budget,checks,validateImport} from './model.mjs';
import {sheetSVG,WIDTH,HEIGHT} from './sheet.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ICONS={user:'M20 21v-2a7 7 0 0 0-14 0v2M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8Z',folder:'M3 7h6l2-3h9a1 1 0 0 1 1 1v14H3Z',layout:'M3 3h18v18H3ZM9 3v18M9 10h12',plus:'M12 5v14M5 12h14',cursor:'m5 3 14 9-7 2-3 7Z',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12ZM12 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6Z',undo:'M8 4 3 9l5 5M3 9h11a7 7 0 0 1 7 7v4',redo:'m16 4 5 5-5 5M21 9H10a7 7 0 0 0-7 7v4',help:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20ZM9 9a3 3 0 1 1 5 2c-1 1-2 1-2 3M12 17h.01',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5','chevron-down':'m6 9 6 6 6-6',move:'M12 2v20M2 12h20M8 6l4-4 4 4M8 18l4 4 4-4M6 8l-4 4 4 4M18 8l4 4-4 4',sliders:'M5 3v18M12 3v18M19 3v18M2 8h6M9 16h6M16 10h6',image:'M3 3h18v18H3Zm0 13 5-5 5 5 3-3 5 5M16 7h.01',file:'M5 2h10l4 4v16H5ZM14 2v6h5M8 13h8M8 17h6',code:'m8 6-6 6 6 6m8-12 6 6-6 6M14 3l-4 18',printer:'M6 8V2h12v6M6 17H3V8h18v9h-3M6 14h12v8H6ZM17 11h.01',lock:'M6 10h12v11H6ZM8 10V6a4 4 0 0 1 8 0v4',unlock:'M6 10h12v11H6ZM8 10V6a4 4 0 0 1 8-1',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7',copy:'M8 8h13v13H8ZM16 8V3H3v13h5',layers:'m12 2 10 6-10 6L2 8Zm-10 10 10 6 10-6M2 17l10 6 10-6','align-left':'M4 3v18M8 6h13M8 12h8M8 18h13','align-center':'M12 2v20M4 6h16M7 12h10M4 18h16','align-right':'M20 3v18M3 6h13M8 12h8M3 18h13',type:'M3 5V3h18v2M12 3v18M7 21h10',diamond:'m12 2 10 10-10 10L2 12Z',minus:'M4 12h16',front:'M8 8h13v13H8ZM3 16V3h13',back:'M3 3h13v13H3ZM8 21h13V8',check:'m4 12 5 5L20 6'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${ICONS[n]||ICONS.layout}"/></svg>`;
function icons(root=document){root.querySelectorAll('[data-icon]').forEach(e=>e.outerHTML=icon(e.dataset.icon));}
icons();
let source,docs=[],doc,db,selected=null,view='character',mode='edit',scale=.4,manualZoom=null,undo=[],redo=[],saveTimer,saveSeq=0,lastHistory=0,uploadTarget='portrait';
const imageCache={};let drag=null,toastTimer;
const getBlock=()=>doc?.blocks.find(b=>b.id===selected);
const selectedName=()=>{const b=getBlock();if(!b)return doc.layoutName||'Composição livre';if(b.type==='ability')return doc.abilities.find(a=>a.id===b.ref)?.title||b.title;return b.title;};
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3600);}
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('catastrophe-atelie-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('fichas',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function dbRequest(mode,action){return new Promise((resolve,reject)=>{const t=db.transaction('fichas',mode);let value;const r=action(t.objectStore('fichas'));r.onsuccess=()=>value=r.result;t.oncomplete=()=>resolve(value);t.onerror=()=>reject(t.error);});}
async function persist(){if(!doc)return;const seq=++saveSeq;const copy=clone(doc);copy.updated=Date.now();const i=docs.findIndex(d=>d.id===copy.id);if(i>=0)docs[i]=copy;else docs.push(copy);try{if(db)await dbRequest('readwrite',s=>s.put(copy));else localStorage.setItem('catastrophe-fallback',JSON.stringify(docs));try{localStorage.setItem('catastrophe-current',copy.id);}catch{}if(seq===saveSeq)$('#saveStatus').textContent='Salvo neste navegador';}catch{$('#saveStatus').textContent='Não foi possível salvar';toast('O navegador não conseguiu salvar. Exporte o arquivo da ficha para guardar seu trabalho.');}}
function scheduleSave(){clearTimeout(saveTimer);$('#saveStatus').textContent='Salvando…';saveTimer=setTimeout(persist,400);}
function history(force=false){if(force||Date.now()-lastHistory>700){undo.push(clone(doc));if(undo.length>35)undo.shift();redo=[];lastHistory=Date.now();}updateHistory();}
function updateHistory(){$('#undoBtn').disabled=!undo.length;$('#redoBtn').disabled=!redo.length;}
function change(fn,panels=false,force=false){history(force);fn();doc.updated=Date.now();draw();scheduleSave();if(panels){renderLeft();renderInspector();}else updateBudget();}
function restore(from,to){if(!from.length)return;to.push(clone(doc));doc=from.pop();selected=null;draw();renderLeft();renderInspector();scheduleSave();updateHistory();}
function switchDoc(id){if(doc)persist();const found=docs.find(d=>d.id===id);if(!found)return;doc=clone(found);selected=null;undo=[];redo=[];manualZoom=null;renderAll();scheduleSave();if(innerWidth<700)$('#leftPanel').classList.add('mobile-closed');}
function renderAll(){renderLeft();renderInspector();draw();updateHistory();requestAnimationFrame(fitCanvas);}
function field(label,body){return `<label class="field"><span>${label}</span>${body}</label>`;}
const input=(value,attrs='',type='text')=>`<input type="${type}" value="${esc(value)}" ${attrs}>`;
const textarea=(value,attrs='')=>`<textarea ${attrs}>${esc(value)}</textarea>`;
function opts(values,value){return values.map(v=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(v)}</option>`).join('');}
function number(label,key,value){return field(label,input(value,`data-doc="${key}" min="0" max="200"`,'number'));}
function updateBudget(){const e=$('#budgetCount');if(e)e.textContent=budget(doc)+'/12 passos';}
function renderLeft(){if(!doc)return;$('#panelTitle').textContent={character:'Personagem',library:'Minhas fichas',layout:'Blocos e layout'}[view];$$('.rail-btn[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const container=$('#leftContent');
 if(view==='character'){
  container.innerHTML=field('Nome do personagem',input(doc.name,'data-doc="name" autocomplete="off"'))+`<div class="two-fields">${field('Perfil',`<select data-doc="profile">${opts(Object.keys(COLORS),doc.profile)}</select>`)}${field('Identificação',input(doc.origin,'data-doc="origin"'))}</div>`+field('Função na equipe',input(doc.role,'data-doc="role"'))+field('Nível / referência (opcional)',input(doc.level,'data-doc="level"'))+field('Nível / referência (opcional)',input(doc.level,'data-doc="level"'))+`<div class="portrait-control">${doc.portrait?`<img src="${esc(doc.portrait)}" alt="Retrato">`:icon('image')}<div><strong>Imagem do personagem</strong><span>PNG, JPG ou WebP</span><button data-action="portrait">Trocar imagem ${icon('upload')}</button></div></div><div class="section"><div class="section-title">Atributos<span class="small-badge">d4 → d12</span></div>${Object.entries(ATTRS).map(([k,label])=>`<label class="attribute-row"><span>${label}</span><select class="dice-select" data-attr="${k}">${STEPS.map(v=>`<option value="${v}" ${doc.attrs[k]===v?'selected':''}>d${v}</option>`).join('')}</select></label>`).join('')}</div><div class="section"><div class="section-title">Recursos<span class="small-badge">PV + PD</span></div><div class="stat-pair"><div class="stat-input"><label>VIDA MÁXIMA<input aria-label="Vida máxima" type="number" min="0" max="200" data-doc="pv" value="${doc.pv}"></label></div><div class="stat-input"><label>DETERMINAÇÃO<input aria-label="Determinação máxima" type="number" min="0" max="200" data-doc="pd" value="${doc.pd}"></label></div></div><div class="two-fields">${number('PV atuais','currentPV',doc.currentPV)}${number('PD atuais','currentPD',doc.currentPD)}</div></div><div class="section"><div class="section-title">Perícias<span id="budgetCount" class="small-badge">${budget(doc)}/12 passos</span></div><input class="skill-filter" id="skillFilter" placeholder="Buscar perícia…" aria-label="Buscar perícia">${source.skills.map(([key,label,attr])=>`<div class="skill-row ${(doc.skills[key]||4)>4?'trained':''}" data-skill-row="${esc(label)}"><label for="skill-${key}">${esc(label.charAt(0)+label.slice(1).toLowerCase())}</label><select id="skill-${key}" data-skill="${key}" title="${esc(label)}">${STEPS.map(v=>`<option value="${v}" ${(doc.skills[key]||4)===v?'selected':''}>d${v}</option>`).join('')}</select></div>`).join('')}</div><div class="section"><div class="section-title">Técnicas e habilidades</div><div class="mini-card" data-action="select-profile"><strong>${PROFILES[doc.profile][0]}</strong><small>Habilidade de ${doc.profile}</small></div>${doc.abilities.map(a=>`<div class="mini-card" data-action="edit-ability" data-id="${a.id}"><strong>${esc(a.title)}</strong><small>Selecionar e editar</small></div>`).join('')}<button class="full-button" data-action="add-ability">${icon('plus')}Adicionar habilidade</button></div><div class="section"><div class="section-title">Rituais<span class="small-badge">${doc.rituals.length}</span></div>${doc.rituals.map(r=>`<div class="mini-card" data-action="edit-ritual" data-id="${r.id}"><strong>${esc(r.title)}</strong><small>${esc(r.meta)}</small></div>`).join('')||'<p class="subtle">Este agente não possui rituais.</p>'}<button class="full-button" data-action="add-ritual">${icon('plus')}Adicionar ritual</button></div><div class="section"><div class="section-title">Equipamento</div>${field('Inventário',textarea(doc.equipment,'data-doc="equipment"'))}${field('Arma principal',input(doc.weapon,'data-doc="weapon"'))}<div class="two-fields">${field('Perícia de ataque',`<select data-doc="attackSkill">${opts(['Luta','Pontaria'],doc.attackSkill)}</select>`)}${field('Dano básico',`<select data-doc="damage">${opts(['RA','RB'],doc.damage)}</select>`)}</div><button class="full-button" data-action="add-combat">${icon('plus')}Mostrar ataque na ficha</button></div><div class="section"><button class="full-button" data-action="validate">${icon('check')}Conferir adaptação</button><p class="subtle">Alterações ficam neste navegador. Exporte o arquivo da ficha para fazer backup ou abrir em outro dispositivo.</p></div>`;
 }else if(view==='library'){
  container.innerHTML=`<p class="subtle">Suas fichas salvas neste navegador. Cada personagem tem sua própria composição.</p><button class="full-button" data-action="new">${icon('plus')}Nova ficha</button>${docs.map(d=>`<div class="library-card ${d.id===doc.id?'active':''}" data-action="open-doc" data-id="${d.id}"><div class="library-name"><span class="mini-profile" style="background:${COLORS[d.profile]}"></span>${esc(d.name)}</div><small>${esc(d.profile)} · ${d.pv} PV · ${d.pd} PD</small><div class="library-actions"><button data-action="duplicate-doc" data-id="${d.id}">${icon('copy')}Duplicar</button><button data-action="delete-doc" data-id="${d.id}">${icon('trash')}Excluir</button></div></div>`).join('')}`;
 }else{
  container.innerHTML=`<p class="subtle">Comece com a estrutura do playtest e organize cada bloco à sua maneira.</p><div class="section-title">Modelos de composição</div><button class="preset-button" data-action="preset" data-preset="ordem"><strong>Ordem Paranormal II</strong><small>Nome no topo, arte central e regras à direita.</small></button><button class="preset-button" data-action="preset" data-preset="duas"><strong>Duas colunas</strong><small>Mais espaço para estatísticas e informações.</small></button><p class="info-line">Aplicar um modelo reorganiza os blocos padrão. Seus dados e poderes são mantidos. Você pode desfazer a alteração.</p><div class="section"><div class="section-title">Blocos livres</div><button class="full-button" data-action="add-block">${icon('plus')}Adicionar bloco</button><p class="subtle">Textos, imagens, marcadores, atributos e perícias. Cada bloco pode ser movido, redimensionado, ocultado ou bloqueado.</p></div><div class="section"><div class="section-title">Aparência da ficha</div>${field('Cor do perfil',`<div class="color-field"><input aria-label="Cor do perfil" type="color" data-doc="accent" value="${doc.accent||COLORS[doc.profile]}"><span>${esc(doc.profile)}</span></div>`)}<button class="quiet" data-action="reset-color">Restaurar cor do perfil</button>${field('Cor do fundo',`<input type="color" aria-label="Cor do fundo" data-doc="background" value="${doc.background}">`)}<label class="toggle-row">Moldura do playtest<input type="checkbox" data-doc="showFrame" ${doc.showFrame?'checked':''}></label></div>`;
 }
}
function renderInspector(){const b=getBlock(),container=$('#inspectorContent');let s='';
 if(!b)s=`<div class="empty-selection">${icon('cursor')}<strong>Seu espaço de criação.</strong><br>Selecione um bloco da ficha para ajustar posição, tamanho e conteúdo.</div>`;
 else{
  const types={name:'Nome',identity:'Perfil',portrait:'Imagem',attributes:'Atributos',skills:'Perícias',resource:'Recursos',profile:'Habilidade de perfil',ability:'Habilidade',equipment:'Equipamento',rituals:'Lista de rituais',text:'Texto livre',image:'Imagem',separator:'Separador',counter:'Marcadores'};
  s=`<div class="block-type">${types[b.type]}</div><h2 style="font-size:17px;margin-bottom:18px">${esc(selectedName())}</h2><div class="property-grid">${['x','y','w','h'].map((k,i)=>field(['Posição X','Posição Y','Largura','Altura'][i],input(Math.round(b[k]),`data-block-prop="${k}" step="1" ${i>1?'min="25"':''}`,'number'))).join('')}</div><div class="align-buttons"><button data-action="align" data-align="left" title="Alinhar à esquerda da página">${icon('align-left')}</button><button data-action="align" data-align="center" title="Centralizar na página">${icon('align-center')}</button><button data-action="align" data-align="right" title="Alinhar à direita da página">${icon('align-right')}</button></div>`;
  if(!['portrait','image','separator'].includes(b.type))s+=`<div class="two-fields">${field('Fonte (px)',input(b.font,'data-block-prop="font" min="12" max="180"','number'))}${field('Alinhamento',`<select data-block-prop="align">${opts(['left','center','right'],b.align)}</select>`)}</div>`;
  s+=field('Cor de destaque',`<input type="color" aria-label="Cor do bloco" data-block-prop="color" value="${b.color||doc.accent||COLORS[doc.profile]}">`)+field('Opacidade',`<input type="range" min="0.1" max="1" step="0.05" data-block-prop="opacity" value="${b.opacity??1}">`);
  if(b.type==='text')s+=field('Título',input(b.title,'data-block-prop="title"'))+field('Conteúdo',textarea(b.body||'','data-block-prop="body"'));
  if(b.type==='name')s+=field('Nome do personagem',input(doc.name,'data-doc="name"'));
  if(b.type==='profile')s+=field('Título',input(b.customTitle||PROFILES[doc.profile][0],'data-block-prop="customTitle"'))+field('Descrição',textarea(b.body??PROFILES[doc.profile][1],'data-block-prop="body"'))+`<button class="quiet" data-action="reset-profile">Restaurar regra do perfil</button>`;
  if(b.type==='ability'){const a=doc.abilities.find(a=>a.id===b.ref);if(a)s+=field('Título',input(a.title,`data-ability-field="title" data-id="${a.id}"`))+field('Descrição',textarea(a.body,`data-ability-field="body" data-id="${a.id}"`));}
  if(b.type==='equipment')s+=field('Inventário',textarea(doc.equipment,'data-doc="equipment"'));
  if(b.type==='resource')s+=field('Recurso',`<select data-block-prop="resource"><option value="pv" ${b.resource==='pv'?'selected':''}>Pontos de vida</option><option value="pd" ${b.resource==='pd'?'selected':''}>Determinação</option></select>`);
  if(b.type==='counter')s+=field('Título',input(b.title,'data-block-prop="title"'))+`<div class="two-fields">${field('Espaços',input(b.max||3,'data-block-prop="max" min="1" max="30"','number'))}${field('Preenchidos',input(b.value||0,'data-block-prop="value" min="0" max="30"','number'))}</div>`;
  if(b.type==='skills'){
   const order=[...(b.skillOrder||[]),...source.skills.map(r=>r[0]).filter(k=>!(b.skillOrder||[]).includes(k))];
   s+=`<label class="toggle-row">Só perícias treinadas<input type="checkbox" data-block-prop="onlyTrained" ${b.onlyTrained?'checked':''}></label><label class="toggle-row">Todas as aptidões<input type="checkbox" data-block-prop="showAllAptitudes" ${b.showAllAptitudes?'checked':''}></label><details><summary class="subtle" style="cursor:pointer;margin:12px 0">Organizar linhas de perícia</summary>${order.map(k=>{const r=source.skills.find(r=>r[0]===k);return r?`<div class="skill-row"><label><input type="checkbox" data-skill-visible="${k}" ${!(b.hiddenSkills||[]).includes(k)?'checked':''}> ${esc(r[1])}</label><button data-action="skill-up" data-key="${k}" title="Mover para cima">↑</button><button data-action="skill-down" data-key="${k}" title="Mover para baixo">↓</button></div>`:'';}).join('')}</details>`;
  }
  if(['portrait','image'].includes(b.type))s+=field('Encaixe',`<select data-block-prop="fit">${opts(['contain','cover'],b.fit||doc.imageFit)}</select>`)+`<button class="full-button" data-action="replace-image">${icon('upload')}Trocar imagem</button>`;
  if(b.type==='rituals')s+=`<p class="subtle">As descrições resumidas são editadas em Personagem → Rituais. Adicione um bloco de texto para destacar um ritual individual.</p><button class="full-button" data-action="add-ritual">${icon('plus')}Adicionar ritual</button>`;
  s+=`<div class="align-buttons"><button data-action="front" title="Trazer à frente">${icon('front')}</button><button data-action="back" title="Enviar para trás">${icon('back')}</button><button data-action="duplicate-block" title="Duplicar bloco">${icon('copy')}</button><button data-action="delete-block" class="danger" title="Remover bloco">${icon('trash')}</button></div><label class="toggle-row">Bloquear posição<input type="checkbox" data-block-prop="locked" ${b.locked?'checked':''}></label><label class="toggle-row">Mostrar na ficha<input type="checkbox" data-block-prop="visible" ${b.visible?'checked':''}></label>`;
 }
 s+=`<div class="section"><div class="section-title">Camadas<button class="icon-btn" data-action="add-block" title="Adicionar bloco">${icon('plus')}</button></div>${doc.blocks.slice().reverse().map(b=>`<div class="layer ${b.id===selected?'active':''} ${b.visible?'':'hidden-layer'}" data-action="select-block" data-id="${b.id}">${icon(b.type==='portrait'||b.type==='image'?'image':b.type==='ability'||b.type==='profile'?'file':'layout')}<span class="layer-name">${esc(b.title)}</span><button data-action="toggle-lock" data-id="${b.id}" title="${b.locked?'Desbloquear':'Bloquear'}">${icon(b.locked?'lock':'unlock')}</button><button data-action="toggle-visible" data-id="${b.id}" title="${b.visible?'Ocultar':'Mostrar'}">${icon('eye')}</button></div>`).join('')}</div>`;
 container.innerHTML=s;
}
function fitCanvas(){if(!doc)return;const v=$('#stageViewport');const width=v.clientWidth-(innerWidth<700?30:innerWidth>1750?110:innerWidth<1250?40:68);scale=manualZoom??Math.max(.12,Math.min(1,width/WIDTH));const w=WIDTH*scale,h=HEIGHT*scale;$('#stageWrap').style.width=w+'px';$('#stageWrap').style.height=h+'px';$('.canvas-caption').style.width=w+'px';$('#zoomValue').textContent=Math.round(scale*100)+'%';renderSelection();}
function draw(){if(!doc)return;$('#documentName').textContent=doc.name;$('#sheet').innerHTML=sheetSVG(doc,source.skills,imageCache,{interactive:true,play:mode==='play'});$('#sheet').classList.toggle('viewing',mode==='play');$('#selectionName').textContent=selectedName();renderSelection();}
function renderSelection(){const b=getBlock();$('#selectionOverlay').innerHTML=b&&mode==='edit'&&b.visible?`<div class="selected-box" style="left:${b.x*scale}px;top:${b.y*scale}px;width:${b.w*scale}px;height:${b.h*scale}px"><span class="selected-label">${esc(selectedName())}${b.locked?' · bloqueado':''}</span>${b.locked?'':'<span class="resize-handle" data-resize="true"></span>'}</div>`:'';}
function select(id,open=false){selected=id;draw();renderInspector();if(open&&innerWidth<1050)$('#inspector').classList.add('open');}
function closeModal(){$('#modal').close();}
function modal(title,body,actions=''){const el=$('#modal');$('#modalContent').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Fechar">×</button></div>${body}${actions?`<div class="modal-actions">${actions}</div>`:''}`;if(!el.open)el.showModal();}
function newModal(){modal('Uma nova ficha.',`<p class="subtle">Escolha um personagem como ponto de partida ou crie seu próprio agente.</p><div class="template-grid">${source.characters.map((c,i)=>`<button class="template-card" data-action="create-template" data-index="${i}"><div class="template-image"><img src="./assets/${c.nome.split(' ')[0].toLowerCase()}.webp" alt="${esc(c.nome)}"></div><div class="template-info"><strong>${esc(c.nome)}</strong><small>${c.perfil} · ${c.pv} PV · ${c.pd} PD</small></div></button>`).join('')}</div>`,`<button class="quiet" data-action="create-blank">Começar em branco</button><button class="quiet" data-action="close-modal">Cancelar</button>`);}
function addBlockModal(){modal('Adicionar à composição',`<p class="subtle">Os blocos podem ser movidos e redimensionados livremente.</p><div class="add-types">${[['text','type','Texto livre'],['image','image','Imagem'],['attributes','diamond','Atributos'],['skills','layout','Perícias'],['resource','layers','PV ou PD'],['counter','diamond','Marcadores'],['separator','minus','Separador'],['equipment','folder','Equipamento']].map(([t,i,l])=>`<button data-action="create-block" data-type="${t}">${icon(i)}${l}</button>`).join('')}</div>`);}
function addNewBlock(type){change(()=>{const title={text:'Nova habilidade',image:'Imagem',attributes:'Atributos',skills:'Perícias',resource:'Pontos de vida',counter:'Marcadores',separator:'Separador',equipment:'Equipamento'}[type]||'Bloco';const b=block(type,title,750,600,type==='separator'?600:500,type==='skills'?700:type==='attributes'?240:type==='image'?500:type==='separator'?25:220,{body:type==='text'?'Escreva a descrição, o custo e o efeito aqui.':'',resource:'pv',max:3,value:0});doc.blocks.push(b);selected=b.id;},true,true);closeModal();if(type==='image'){uploadTarget=selected;$('#portraitFile').click();}}
function addAbility(){change(()=>{const a={id:uid(),title:'Nova habilidade',body:'Descreva o custo, a ação e o efeito da habilidade.'};doc.abilities.push(a);const b=block('ability',a.title,1150,650,625,225,{ref:a.id});doc.blocks.push(b);selected=b.id;},true,true);if(innerWidth<1050)$('#inspector').classList.add('open');}
function ritualModal(id){const r=doc.rituals.find(r=>r.id===id);if(!r)return;modal('Editar ritual',field('Nome',input(r.title,`data-ritual-field="title" data-id="${r.id}"`))+field('Elemento, custo, ação e alcance',input(r.meta,`data-ritual-field="meta" data-id="${r.id}"`))+field('Resumo na ficha',textarea(r.summary,`data-ritual-field="summary" data-id="${r.id}"`))+field('Descrição completa',textarea(r.body,`data-ritual-field="body" data-id="${r.id}"`)),`<button class="quiet danger" data-action="delete-ritual" data-id="${r.id}">Remover ritual</button><button class="quiet" data-action="ritual-block" data-id="${r.id}">Criar bloco completo</button><button class="primary" data-action="finish-ritual">Concluir</button>`);}
function addRitualModal(){const all=Object.values(source.spells).flat();modal('Adicionar ritual',`<p class="subtle">Versões já convertidas para Catastrophe. Você também pode escrever um ritual próprio.</p>${field('Ritual',`<select id="ritualChoice"><option value="custom">Ritual personalizado</option>${all.map((r,i)=>`<option value="${i}">${esc(r[0])}</option>`).join('')}</select>`)}<div class="info-line">Adicionar um ritual altera o repertório do personagem; os poderes dos modelos são sugestões para a versão do passado.</div>`,`<button class="quiet" data-action="close-modal">Cancelar</button><button class="primary" data-action="confirm-ritual">Adicionar</button>`);}
async function createDoc(d){await persist();docs.push(d);doc=d;selected=null;undo=[];redo=[];view='character';closeModal();renderAll();scheduleSave();}
function libraryDelete(id){const d=docs.find(x=>x.id===id);if(!d)return;modal('Excluir esta ficha?',`<p class="subtle">${esc(d.name)} será removido deste navegador. Exporte o arquivo da ficha antes se quiser guardá-lo.</p>`,`<button class="quiet" data-action="close-modal">Cancelar</button><button class="primary" data-action="confirm-delete-doc" data-id="${id}">Excluir ficha</button>`);}
function help(){modal('Do modelo à sua ficha.',`<ol class="help-list"><li><strong>Edite o agente.</strong> Use Personagem para alterar atributos, perícias, recursos e poderes.</li><li><strong>Organize a página.</strong> Arraste os blocos, puxe o canto inferior direito para redimensionar ou use os campos de posição. As camadas definem o que fica à frente.</li><li><strong>Personalize.</strong> Adicione imagens, textos e marcadores. Bloqueie o retrato para organizar os textos sem movê-lo por acidente.</li><li><strong>Visualize e acompanhe.</strong> Em Visualizar, clique nos pontos de PV, PD e marcadores para preenchê-los.</li><li><strong>Guarde seu trabalho.</strong> O salvamento é neste navegador. Exporte JSON para backup e PNG para compartilhar.</li></ol><p class="subtle"><kbd>Ctrl Z</kbd> desfaz · <kbd>Ctrl Shift Z</kbd> refaz · <kbd>← ↑ ↓ →</kbd> move o bloco · <kbd>Shift</kbd> move 10 px · <kbd>Delete</kbd> remove o bloco.</p>`,`<button class="primary" data-action="close-modal">Entendi</button>`);}
function handleAction(action,el){const b=getBlock(),id=el.dataset.id;
 switch(action){
 case 'new':newModal();break;case 'close-modal':closeModal();break;case 'create-template':createDoc(makeCharacter(source.characters[+el.dataset.index],source.details,source.spells,source.summaries));break;case 'create-blank':createDoc(blank());break;
 case 'open-doc':switchDoc(id);break;case 'duplicate-doc':{const copy=clone(docs.find(d=>d.id===id));copy.id=uid();copy.name+=' — cópia';createDoc(copy);view='library';renderLeft();break;}
 case 'delete-doc':libraryDelete(id);break;case 'confirm-delete-doc':(async()=>{clearTimeout(saveTimer);if(db)await dbRequest('readwrite',s=>s.delete(id));docs=docs.filter(d=>d.id!==id);if(!db)localStorage.setItem('catastrophe-fallback',JSON.stringify(docs));if(doc.id===id){doc=clone(docs[0]||blank());if(!docs.length)docs.push(doc);selected=null;}closeModal();renderAll();scheduleSave();toast('Ficha excluída deste navegador.');})();break;
 case 'portrait':uploadTarget='portrait';$('#portraitFile').click();break;case 'replace-image':uploadTarget=b?.type==='portrait'?'portrait':selected;$('#portraitFile').click();break;
 case 'select-profile':select(doc.blocks.find(b=>b.type==='profile')?.id,true);break;case 'select-block':select(id,true);break;case 'edit-ability':select(doc.blocks.find(b=>b.ref===id)?.id,true);break;
 case 'toggle-visible':change(()=>{const target=doc.blocks.find(b=>b.id===id);target.visible=!target.visible;},false,true);renderInspector();break;case 'toggle-lock':change(()=>{const target=doc.blocks.find(b=>b.id===id);target.locked=!target.locked;},false,true);renderInspector();break;
 case 'add-block':addBlockModal();break;case 'create-block':addNewBlock(el.dataset.type);break;case 'add-ability':addAbility();break;case 'add-ritual':addRitualModal();break;case 'edit-ritual':ritualModal(id);break;
 case 'confirm-ritual':{const choice=$('#ritualChoice').value,all=Object.values(source.spells).flat();let r;if(choice==='custom')r={id:uid(),title:'Novo ritual',meta:'ELEMENTO / CUSTO / AÇÃO / ALCANCE',summary:'Descreva o efeito resumido.',body:'Descreva o efeito completo.'};else{const [title,meta,body]=all[+choice];r={id:uid(),title,meta,body,summary:Object.values(source.summaries).flat().find(s=>s[0]===title)?.[1]||body};}change(()=>{doc.rituals.push(r);if(!doc.blocks.some(b=>b.type==='rituals'))doc.blocks.push(block('rituals','Rituais',1150,810,625,490,{font:22}));},true,true);ritualModal(r.id);break;}
 case 'delete-ritual':change(()=>{doc.rituals=doc.rituals.filter(r=>r.id!==id);},true,true);closeModal();break;
 case 'finish-ritual':closeModal();renderLeft();renderInspector();break;case 'ritual-block':{const r=doc.rituals.find(r=>r.id===id);change(()=>{const added=block('text',r.title,550,600,780,450,{body:r.meta+'\n'+r.body,font:23});doc.blocks.push(added);selected=added.id;},true,true);closeModal();break;}
 case 'preset':change(()=>{layout(doc,el.dataset.preset);selected=null;},true,true);toast('Composição aplicada. Ctrl+Z para desfazer.');break;
 case 'reset-color':change(()=>doc.accent=null,true,true);break;case 'reset-profile':if(b)change(()=>{delete b.body;delete b.customTitle;},true,true);break;
 case 'skill-up':case 'skill-down':if(b)change(()=>{const order=[...(b.skillOrder||[]),...source.skills.map(r=>r[0]).filter(k=>!(b.skillOrder||[]).includes(k))];const index=order.indexOf(el.dataset.key),other=index+(action==='skill-up'?-1:1);if(other>=0&&other<order.length)[order[index],order[other]]=[order[other],order[index]];b.skillOrder=order;},false,true);renderInspector();break;
 case 'align':if(b)change(()=>{b.x={left:80,center:(WIDTH-b.w)/2,right:WIDTH-80-b.w}[el.dataset.align];},true,true);break;
 case 'front':if(b)change(()=>{doc.blocks=doc.blocks.filter(x=>x.id!==b.id);doc.blocks.push(b);},true,true);break;case 'back':if(b)change(()=>{doc.blocks=doc.blocks.filter(x=>x.id!==b.id);doc.blocks.unshift(b);},true,true);break;
 case 'duplicate-block':if(b)change(()=>{const c=clone(b);c.id=uid();c.x+=25;c.y+=25;if(c.type==='ability'){const a=clone(doc.abilities.find(a=>a.id===c.ref));a.id=uid();a.title+=' — cópia';doc.abilities.push(a);c.ref=a.id;c.title=a.title;}doc.blocks.push(c);selected=c.id;},true,true);break;
 case 'delete-block':if(b)change(()=>{doc.blocks=doc.blocks.filter(x=>x.id!==b.id);selected=null;},true,true);break;
 case 'add-combat':change(()=>{const sk=doc.skills[doc.attackSkill]||4;const added=block('text',doc.weapon,720,1000,550,160,{body:`Físico d${doc.attrs.Fisico} + ${doc.attackSkill} d${sk}. Dano: ${doc.damage}.\n${doc.weaponNote}`,font:21});doc.blocks.push(added);selected=added.id;},true,true);toast('Bloco de ataque criado com os valores atuais.');break;
 case 'validate':{const cs=checks(doc);modal('Conferência da adaptação',`<p class="subtle">Referência de criação usada nas seis versões do passado. Você pode personalizar os valores sem bloquear a ficha.</p><div class="check-results ${cs.every(c=>c.ok)?'':'warn'}">${cs.map(c=>(c.ok?'✓':'○')+' '+c.text).join('<br>')}</div><p class="subtle" style="margin-top:18px">Perfil não define função de combate. A validação não substitui o equilíbrio de habilidades e rituais em mesa.</p>`,`<button class="primary" data-action="close-modal">Concluir</button>`);break;}
 }
}
document.addEventListener('click',e=>{const action=e.target.closest('[data-action]');if(action){e.stopPropagation();handleAction(action.dataset.action,action);}if(!e.target.closest('#exportBtn,#exportMenu'))$('#exportMenu').hidden=true;});
document.addEventListener('input',e=>{const el=e.target;if(!doc)return;
 if(el.id==='skillFilter'){$$('[data-skill-row]').forEach(r=>r.hidden=!r.dataset.skillRow.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(el.value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()));return;}
 if(el.dataset.doc){const key=el.dataset.doc;change(()=>{let value=el.type==='checkbox'?el.checked:el.value;if(['pv','pd','currentPV','currentPD'].includes(key))value=clamp(value,0,200);if(key==='currentPV')value=Math.min(value,doc.pv);if(key==='currentPD')value=Math.min(value,doc.pd);if(key==='currentPV')value=Math.min(value,doc.pv);if(key==='currentPD')value=Math.min(value,doc.pd);doc[key]=value;if(key==='pv')doc.currentPV=Math.min(doc.currentPV,value);if(key==='pd')doc.currentPD=Math.min(doc.currentPD,value);if(key==='profile'){doc.accent=null;for(const b of doc.blocks.filter(b=>b.type==='profile')){delete b.body;delete b.customTitle;}}},key==='profile');return;}
 if(el.dataset.attr){change(()=>doc.attrs[el.dataset.attr]=+el.value);return;}
 if(el.dataset.skill){change(()=>doc.skills[el.dataset.skill]=+el.value);el.closest('.skill-row')?.classList.toggle('trained',+el.value>4);return;}
 if(el.dataset.skillVisible){const b=getBlock();if(b)change(()=>{b.hiddenSkills=(b.hiddenSkills||[]).filter(k=>k!==el.dataset.skillVisible);if(!el.checked)b.hiddenSkills.push(el.dataset.skillVisible);});return;}
 if(el.dataset.blockProp){const b=getBlock();if(!b)return;const key=el.dataset.blockProp;change(()=>{let value=el.type==='checkbox'?el.checked:el.value;if(['x','y'].includes(key))value=clamp(value,-500,4000);if(['w','h'].includes(key))value=clamp(value,25,4000);if(key==='font')value=clamp(value,12,180);if(key==='opacity')value=clamp(value,.1,1);if(key==='max')value=clamp(value,1,30);if(key==='value')value=clamp(value,0,b.max||30);b[key]=value;});return;}
 if(el.dataset.abilityField){const a=doc.abilities.find(a=>a.id===el.dataset.id);change(()=>{a[el.dataset.abilityField]=el.value;if(el.dataset.abilityField==='title'){const b=doc.blocks.find(b=>b.ref===a.id);if(b)b.title=el.value;}});return;}
 if(el.dataset.ritualField){const r=doc.rituals.find(r=>r.id===el.dataset.id);change(()=>r[el.dataset.ritualField]=el.value);return;}
});
$$('[data-view]').forEach(b=>b.addEventListener('click',()=>{const same=view===b.dataset.view;view=b.dataset.view;renderLeft();if(innerWidth<700)$('#leftPanel').classList.toggle('mobile-closed',same?!$('#leftPanel').classList.contains('mobile-closed'):false);}));
$('#newBtn').onclick=newModal;$('#helpBtn').onclick=help;$('#undoBtn').onclick=()=>restore(undo,redo);$('#redoBtn').onclick=()=>restore(redo,undo);
$('#editMode').onclick=()=>{mode='edit';$('#editMode').classList.add('active');$('#playMode').classList.remove('active');$('#canvasHint').textContent='Selecione um bloco para editar. Arraste para reorganizar.';draw();};
$('#playMode').onclick=()=>{mode='play';$('#playMode').classList.add('active');$('#editMode').classList.remove('active');$('#canvasHint').textContent='Clique nos pontos de PV, PD ou marcadores para acompanhar os recursos.';draw();};
$('#fitBtn').onclick=()=>{manualZoom=null;fitCanvas();};$('#zoomValue').onclick=()=>{manualZoom=null;fitCanvas();};$('#zoomIn').onclick=()=>{manualZoom=Math.min(1.5,scale+.1);fitCanvas();};$('#zoomOut').onclick=()=>{manualZoom=Math.max(.15,scale-.1);fitCanvas();};
$('#mobileInspector').onclick=()=>$('#inspector').classList.toggle('open');$('#closeInspector').onclick=()=>$('#inspector').classList.remove('open');
new ResizeObserver(()=>fitCanvas()).observe($('#stageViewport'));
$('#sheet').addEventListener('pointerdown',e=>{
 if(!doc)return;if(mode==='play'){const target=e.target.closest('[data-point]');if(!target)return;const n=+target.dataset.point;change(()=>{if(target.dataset.resource){const key=target.dataset.resource==='pv'?'currentPV':'currentPD';doc[key]=n<=doc[key]?n-1:n;}else{const b=doc.blocks.find(b=>b.id===target.dataset.counter);b.value=n<=(b.value||0)?n-1:n;}},false,true);renderLeft();renderInspector();return;}
 const el=e.target.closest('[data-block]');if(!el){select(null);return;}const id=el.dataset.block;select(id);const b=getBlock();if(b.locked)return;startDrag(e,'move',b);
});
$('#selectionOverlay').addEventListener('pointerdown',e=>{if(e.target.dataset.resize){e.stopPropagation();startDrag(e,'resize',getBlock());}});
function startDrag(e,type,b){if(!b)return;e.preventDefault();drag={type,id:b.id,startX:e.clientX,startY:e.clientY,rect:clone(b),before:clone(doc),moved:false};}
window.addEventListener('pointermove',e=>{if(!drag)return;const b=doc.blocks.find(b=>b.id===drag.id);let dx=(e.clientX-drag.startX)/scale,dy=(e.clientY-drag.startY)/scale;if(Math.abs(dx)+Math.abs(dy)<2)return;drag.moved=true;const snap=v=>$('#snapToggle').checked&&!e.altKey?Math.round(v/10)*10:Math.round(v);if(drag.type==='move'){b.x=clamp(snap(drag.rect.x+dx),0,WIDTH-40);b.y=clamp(snap(drag.rect.y+dy),0,HEIGHT-30);}else{b.w=clamp(snap(drag.rect.w+dx),80,WIDTH);b.h=clamp(snap(drag.rect.h+dy),35,HEIGHT);}draw();});
window.addEventListener('pointerup',()=>{if(!drag)return;if(drag.moved){undo.push(drag.before);if(undo.length>35)undo.shift();redo=[];scheduleSave();renderInspector();updateHistory();}drag=null;});
window.addEventListener('keydown',e=>{if($('#modal').open||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?restore(redo,undo):restore(undo,redo);return;}const b=getBlock();if(!b||b.locked||mode!=='edit')return;if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();handleAction('delete-block',{});}if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const n=e.shiftKey?10:1;change(()=>{if(e.key==='ArrowLeft')b.x-=n;if(e.key==='ArrowRight')b.x+=n;if(e.key==='ArrowUp')b.y-=n;if(e.key==='ArrowDown')b.y+=n;},false,true);renderInspector();}});
function fileData(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});}
async function imageData(src){if(!src||src.startsWith('data:'))return src;if(imageCache[src])return imageCache[src];const response=await fetch(src);if(!response.ok)throw Error('Não foi possível carregar uma imagem.');const raw=await response.blob();const typed=raw.type.startsWith('image/')?raw:new Blob([raw],{type:src.endsWith('.webp')?'image/webp':'image/png'});const data=await fileData(typed);imageCache[src]=data;return data;}
$('#portraitFile').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;if(f.size>12e6){toast('Escolha uma imagem de até 12 MB.');return;}try{const data=await fileData(f);const im=new Image();im.src=data;await im.decode();const canvas=document.createElement('canvas');const ratio=Math.min(1,1800/Math.max(im.width,im.height));canvas.width=Math.max(1,Math.round(im.width*ratio));canvas.height=Math.max(1,Math.round(im.height*ratio));canvas.getContext('2d').drawImage(im,0,0,canvas.width,canvas.height);const compact=canvas.toDataURL('image/webp',.94);change(()=>{if(uploadTarget==='portrait')doc.portrait=compact;else{const b=doc.blocks.find(b=>b.id===uploadTarget);if(b)b.image=compact;}},true,true);toast('Imagem adicionada.');}catch{toast('Não foi possível abrir essa imagem. Use PNG, JPG ou WebP.');}};
$('#importBtn').onclick=()=>$('#importFile').click();$('#importFile').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;if(f.size>20e6){toast('O arquivo da ficha deve ter até 20 MB.');return;}try{const imported=validateImport(JSON.parse(await f.text()));imported.id=uid();await createDoc(imported);toast('Ficha importada, com dados e composição.');}catch(err){toast(err.message||'Não foi possível importar a ficha.');}};
$('#exportBtn').onclick=()=>$('#exportMenu').hidden=!$('#exportMenu').hidden;
function download(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
const slug=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'agente';
async function embedded(d){for(const b of d.blocks.filter(b=>b.type==='image'))if(b.image)await imageData(b.image);if(d.portrait)await imageData(d.portrait);}
async function exportDoc(type){$('#exportMenu').hidden=true;if(type==='print'){window.print();return;}document.body.classList.add('busy');toast('Preparando sua ficha…');try{await embedded(doc);const name=slug(doc.name);if(type==='json'){const portable=clone(doc);portable.portrait=await imageData(portable.portrait);for(const b of portable.blocks)if(b.image)b.image=await imageData(b.image);download(new Blob([JSON.stringify(portable,null,2)],{type:'application/json'}),name+'.catastrophe.json');toast('Arquivo da ficha exportado.');return;}
 const body=sheetSVG(doc,source.skills,imageCache,{interactive:false}),svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${WIDTH}" height="${HEIGHT}" viewBox="0 0 ${WIDTH} ${HEIGHT}">${body}</svg>`;
 if(type==='svg'){download(new Blob([svg],{type:'image/svg+xml'}),name+'.svg');toast('Imagem SVG exportada.');return;}
 const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));try{const image=new Image();image.src=url;await image.decode();const canvas=document.createElement('canvas');canvas.width=WIDTH*2;canvas.height=HEIGHT*2;canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('A imagem não pôde ser gerada.');download(blob,name+'.png');toast('PNG exportado em 3840 × 2862.');}finally{URL.revokeObjectURL(url);}
 }catch(err){toast('Não foi possível exportar: '+err.message);}finally{document.body.classList.remove('busy');}}
$$('[data-export]').forEach(b=>b.onclick=()=>exportDoc(b.dataset.export));
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal();});
window.addEventListener('pagehide',()=>{if(doc)persist();});
async function init(){try{const r=await fetch('./presets.json');if(!r.ok)throw Error('Modelos indisponíveis.');source=await r.json();try{db=await openDB();docs=await dbRequest('readonly',s=>s.getAll());}catch{try{docs=JSON.parse(localStorage.getItem('catastrophe-fallback')||'[]');}catch{docs=[];}}
 docs=docs.filter(d=>{try{validateImport(d);return true;}catch{return false;}});if(!docs.length){docs=source.characters.map(c=>makeCharacter(c,source.details,source.spells,source.summaries));if(db)for(const d of docs)await dbRequest('readwrite',s=>s.put(d));}
 let current;try{current=localStorage.getItem('catastrophe-current');}catch{}doc=clone(docs.find(d=>d.id===current)||docs.find(d=>d.name==='Lian Rosseul')||docs[0]);try{localStorage.setItem('catastrophe-current',doc.id);}catch{}if(innerWidth<700)$('#leftPanel').classList.add('mobile-closed');renderAll();$('#saveStatus').textContent='Salvo neste navegador';Promise.all(source.characters.map(c=>imageData(`./assets/${c.nome.split(' ')[0].toLowerCase()}.webp`))).then(draw).catch(()=>{});
 }catch(err){$('#saveStatus').textContent='Falha ao carregar';$('#leftContent').innerHTML=`<p class="subtle">Não foi possível abrir o editor. Recarregue a página para tentar novamente.</p>`;toast(err.message);}}
init();
